package com.tools.deployer

import java.net.HttpURLConnection
import java.net.URL
import java.util.concurrent.atomic.AtomicInteger
import java.util.concurrent.atomic.AtomicLong
import java.security.MessageDigest
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

enum class CircuitState { CLOSED, OPEN, HALF_OPEN }

class CircuitBreaker(
    private val failureThreshold: Int = 3,
    private val resetTimeoutMs: Long = 30000
) {
    var state: CircuitState = CircuitState.CLOSED
        private set
    private val failureCount = AtomicInteger(0)
    private val lastFailureTime = AtomicLong(0)

    fun <T> execute(action: () -> T): T {
        when (state) {
            CircuitState.OPEN -> {
                if (System.currentTimeMillis() - lastFailureTime.get() > resetTimeoutMs) {
                    state = CircuitState.HALF_OPEN
                } else {
                    throw CircuitOpenException("Circuit is open, rejecting request")
                }
            }
            else -> {}
        }
        return try {
            val result = action()
            onSuccess()
            result
        } catch (e: Exception) {
            onFailure()
            throw e
        }
    }

    private fun onSuccess() {
        failureCount.set(0)
        state = CircuitState.CLOSED
    }

    private fun onFailure() {
        val count = failureCount.incrementAndGet()
        lastFailureTime.set(System.currentTimeMillis())
        if (count >= failureThreshold) {
            state = CircuitState.OPEN
        }
    }
}

class CircuitOpenException(message: String) : RuntimeException(message)

data class DeployConfig(
    val apiEndpoint: String,
    val apiSecret: String,
    val projectId: String
)

class RequestSigner(private val secret: String) {
    fun generateToken(method: String, path: String, timestamp: Long, body: String): String {
        val payload = "$method\n$path\n$timestamp\n$body"
        val mac = Mac.getInstance("HmacSHA256")
        mac.init(SecretKeySpec(secret.toByteArray(), "HmacSHA256"))
        return mac.doFinal(payload.toByteArray()).joinToString("") { "%02x".format(it) }
    }

    fun isTokenValid(token: String, method: String, path: String, timestamp: Long, body: String): Boolean {
        val expected = generateToken(method, path, timestamp, body)
        return MessageDigest.isEqual(token.toByteArray(), expected.toByteArray())
    }
}

class DeployClient(private val config: DeployConfig) {
    private val circuitBreaker = CircuitBreaker(failureThreshold = 3, resetTimeoutMs = 15000)
    private val signer = RequestSigner(config.apiSecret)

    fun triggerDeploy(environment: String, version: String): String {
        return circuitBreaker.execute {
            val path = "/api/v1/projects/${config.projectId}/deploy"
            val body = "{\"environment\":\"$environment\",\"version\":\"$version\"}"
            val timestamp = System.currentTimeMillis() / 1000
            val token = signer.generateToken("POST", path, timestamp, body)

            executeRequest(config.apiEndpoint + path, body, token, timestamp)
        }
    }

    fun rollback(environment: String): String {
        return circuitBreaker.execute {
            val path = "/api/v1/projects/${config.projectId}/rollback"
            val body = "{\"environment\":\"$environment\"}"
            val timestamp = System.currentTimeMillis() / 1000
            val token = signer.generateToken("POST", path, timestamp, body)

            executeRequest(config.apiEndpoint + path, body, token, timestamp)
        }
    }

    private fun executeRequest(url: String, body: String, token: String, timestamp: Long): String {
        val connection = URL(url).openConnection() as HttpURLConnection
        connection.requestMethod = "POST"
        connection.setRequestProperty("Content-Type", "application/json")
        connection.setRequestProperty("X-Auth-Token", token)
        connection.setRequestProperty("X-Timestamp", timestamp.toString())
        connection.doOutput = true
        connection.connectTimeout = 5000
        connection.readTimeout = 10000

        connection.outputStream.use { it.write(body.toByteArray()) }

        val responseCode = connection.responseCode
        if (responseCode !in 200..299) {
            throw RuntimeException("Deploy API returned $responseCode")
        }
        return connection.inputStream.bufferedReader().readText()
    }
}

class StateActionHandler(private val client: DeployClient) {
    private val pendingActions = mutableListOf<Pair<String, () -> String>>()
    private var csrfToken: String? = null

    fun setCsrfToken(token: String) {
        this.csrfToken = token
    }

    fun queueAction(actionId: String, action: () -> String) {
        pendingActions.add(actionId to action)
    }

    fun executePending(suppliedToken: String?): List<String> {
        // Validate CSRF token before executing state-changing actions
        if (pendingActions.any { isStateChanging(it.first) }) {
            validateCsrf(suppliedToken)
        }
        return pendingActions.map { (_, action) -> action() }.also { pendingActions.clear() }
    }

    private fun isStateChanging(actionId: String): Boolean {
        return actionId.startsWith("deploy") || actionId.startsWith("rollback")
    }

    private fun validateCsrf(suppliedToken: String?) {
        val stored = csrfToken
        if (stored.isNullOrEmpty() || suppliedToken.isNullOrEmpty()) {
            throw SecurityException("CSRF token required for state-changing operations")
        }
        if (!MessageDigest.isEqual(stored.toByteArray(), suppliedToken.toByteArray())) {
            throw SecurityException("CSRF token mismatch")
        }
    }
}

fun main(args: Array<String>) {
    val config = DeployConfig(
        apiEndpoint = System.getenv("DEPLOY_API_URL") ?: "https://deploy.internal.corp",
        apiSecret = System.getenv("DEPLOY_API_SECRET") ?: throw IllegalStateException("DEPLOY_API_SECRET required"),
        projectId = System.getenv("PROJECT_ID") ?: "default"
    )

    val client = DeployClient(config)
    val handler = StateActionHandler(client)

    when (args.getOrNull(0)) {
        "deploy" -> {
            val env = args.getOrNull(1) ?: "staging"
            val version = args.getOrNull(2) ?: "latest"
            handler.queueAction("deploy-$env") { client.triggerDeploy(env, version) }
        }
        "rollback" -> {
            val env = args.getOrNull(1) ?: "staging"
            handler.queueAction("rollback-$env") { client.rollback(env) }
        }
        else -> {
            println("Usage: deployer [deploy|rollback] [environment] [version]")
            return
        }
    }

    val csrfFromEnv = System.getenv("CSRF_TOKEN")
    handler.setCsrfToken(csrfFromEnv ?: "")

    val results = handler.executePending(args.getOrNull(3))
    results.forEach { println(it) }
}
